package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.*;
/** Source all-state joining basis and old alias, independently captured before portable adaptation. */
public final class ScreenJoinGeometryChecks {
 public static void main(String[] args)throws Exception{JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenJoinGeometryReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0;for(var entry:reference.getAsJsonArray("cases")){var source=entry.getAsJsonObject();var family=ScreenFamily.fromId(source.get("id").getAsString());var basis=ScreenJoinGeometry.basis(family,family.decode(source.get("meta").getAsInt()),source.get("ceiling").getAsBoolean());if(basis.right!=source.get("right").getAsInt()||basis.up!=source.get("up").getAsInt()||ScreenJoinGeometry.supports(family,source.get("small").getAsBoolean())!=source.get("supported").getAsBoolean())throw new AssertionError("Joining orientation differs "+source);for(int i=0;i<4;i++){var step=source.getAsJsonArray("steps").get(i).getAsJsonArray();if(basis.dx(i)!=step.get(0).getAsInt()||basis.dy(i)!=step.get(1).getAsInt()||basis.dz(i)!=step.get(2).getAsInt())throw new AssertionError("Joining step differs");}int[][] probes={{-2,79,3},{0,80,0},{3,81,-5}};for(int i=0;i<3;i++)if(basis.cell(probes[i][0],probes[i][1],probes[i][2])!=source.getAsJsonArray("cells").get(i).getAsLong())throw new AssertionError("Joining lattice cell differs");cases++;}if(cases!=328||!reference.get("sha256").getAsString().equals("5496c7a4292d4e2ce8513af3398430e7938bf5b3eb07d59526c0bdbd570ecad0"))throw new AssertionError("Source joining coverage");System.out.println("Native portable Screen joining geometry PASS actual Source states/alias="+cases);}
}
